"""«Топы запросов» Вордстата (выгрузки пользователя 21.10.2026): классификация фраз по намерению и критериям выбора.
Вход: notes/raw_wordstat/top_*.csv. Выход: data/ws_tops.csv (фразы с классами), data/ws_tops_intents.csv (доли).
Доли считаются от суммы частот фраз без главного запроса; фразы вложены друг в друга, поэтому доли — оценка структуры спроса."""
import csv, glob, os, re
B = '/home/claude/zabory'
INTENT = [  # порядок важен: первый совпавший класс
    ('сметы, коды и закупки', r'окпд|оквэд|косгу|гэсн|тендер|акт выполн|техническое задание|расценка в смете|сканворд'),
    ('правовой вопрос', r'сосед|соглас|\bправила\b|правил установ|\bнормы\b|нормы установ|норматив|закон|разрешен|снт|ижс|погрешн|границ|оспор|охранной зоне|по закону|обязанность'),
    ('своими руками', r'правильн|своими руками|как сделать|как установить|как подключить|чертеж|схем|пошагов|инструкц|видео|самому|самостоят|с чего начать|технолог|способ|хитрый|самодел|приспособ|шаблон|кондуктор|уровень для|приблуд|держател|как ровно|гидроуровень|как выровнять|как пользоваться|своим материал'),
    ('цена и заказ', r'цен|стоим|сколько|прайс|расцен|смет|купить|заказ|под ключ|ключ установк|с установк|услуг|фирм|компан|мастер|бригад|рабоч|организац|недорог|рассроч|договор|рейтинг|лучшие фирм|авито|телефон|отзыв|бизнес'),
    ('ремонт и обслуживание', r'ремонт|настройк|обслужив|регулиров|не работает|не закрыва|не открыва'),
    ('бренд производителя', r'алютех|alutech|дорхан|doorhan|came|nice|ролтек|an-motors|ан моторс|гранд лайн|велбор|махаон'),
    ('комплектующие и автоматика', r'привод|автоматик|ролик|балк|направляющ|комплект|каркас|фурнитур|бур\b|бур для|пульт|подключен|консол|опор|столб|свай|сваи|стоек|стойк|опалубк|ламел|парапет|отлив|планк|прожилин|капельник|замок|замка|бордюр|поребрик|труб|егоз|колюч|сетка кладоч|пена|смесь|мотор|двигател|рейк|фотоэлем|профиль для|швеллер|закладн|фундамент|управлен'),
    ('гео (город, регион)', r'спб|петербург|ленинград|области|обл\b|москв|подмоск|тул|ярослав|екатеринбург|тюмен|омск|воронеж|новосибир|хабаров|киров|рязан|владимир|севастоп|крым|казан|самар|уф[аеы]|пенз|челяб|калинин|костром|смоленск|орл[ае]|орел|брянск|калуг|липец|иваново|перм|иркутск|ростов|новгород|саратов|ижевск|череповец|волгоград|кемеров|барнаул|твер|архангел|симфероп|краснодар|сочи|псков|ульянов|чебоксар|вологд|мурманск|сыктывкар|тольят|белгород|красноярск|тагил|днр|лнр|донецк|луганск|минск|гомел|могил|витебск|алматы|курск|астрахан|стерлит|кропоткин|ессентук|феодос|керч|коктебел|ялуторов|рыбинск|киржач|тихвин|кингисепп|старый оскол|междуреченск|сарапул|копейск|томск|чита|южно|северодвинск|котлас|абаз|великих лук|великий|камышин|сасов|богородицк|кушв|среднеуральск|александров|тайцах|хомутов|арамил|партизанск|ставрополь|нижний|нижн|иркут'),
    ('выбор и параметры', r'какие|какой|лучше|размер|метр|длин|высот|ширин|фото|верхн|автоматическ|виды|типы|с калиткой|горизонтально|глух|металлическ|железн|профильн'),
    ('монтаж и изготовление', r'установк|монтаж|изготовл|сборк|сварк|устанавл'),
]
CRIT = [
    ('цена работы отдельно от материала', r'за работу|без материал|материала заказчика|своим материал|цена работы|стоимость работ'),
    ('цена за метр', r'за метр|погонн|1 метра|за 1м|метра\b|за м\b'),
    ('рассрочка', r'рассроч'),
    ('уклон и сложный участок', r'уклон|склон|перепад|неровн|разных уровнях|каскад|болот|пучинист|глинист|глинян'),
    ('фундамент и столбы', r'бетонир|бутован|фундамент|свай|сваи|столб|копер|ленточн|винтов'),
    ('с воротами и калиткой', r'ворот|калитк'),
    ('договор и документы', r'договор|смет|акт выполн'),
    ('соседи и границы', r'сосед|границ|снт|ижс'),
    ('зимний монтаж', r'зимой'),
    ('автоматика', r'привод|автоматик|пульт|подключ'),
]
MAT = [('профнастил / профлист', r'профнаст|профлист|металлопроф|профильн\w* забор|профильного листа'), ('евроштакетник / штакетник', r'штакет'), ('3D-сетка / гиттер', r'3д|3 д|3d|3 d|три д|триде|зд забор|гиттер'),
       ('рабица / сетка', r'рабиц|сетк|евросетк'), ('жалюзи', r'жалюзи'), ('бетон / кирпич', r'бетон|железобетон|кирпич|блок'), ('дерево', r'дерев|досок|горбыл|дпк|плетен')]
BRAND = r'алютех|дорхан|doorhan|came|nice|ролтек|an-motors|ан моторс|мастеровит|гранд лайн|велбор|махаон|частокол|московские заборы'
rows, summ = [], []
for f in sorted(glob.glob(f'{B}/notes/raw_wordstat/top_*.csv')):
    t = open(f, encoding='utf-8-sig').read().replace('\r', '\n')
    m = re.search(r'Топ частотных запросов «(.+?)», (\S+) — (\S+), (.+?), все устройства', t)
    q, reg = m.group(1), ('Россия без 16 областей Центра (Москва и МО входят)' if 'Белгородская' in m.group(4) else m.group(4))
    tok = [x.strip() for x in t[m.end():].replace('\n', ';').split(';') if x.strip()]
    ph = [(tok[i], int(tok[i + 1])) for i in range(0, len(tok) - 1, 2)]
    head = ph[0]
    for p, c in ph[1:]:
        comp_rx = dict(INTENT)['комплектующие и автоматика']
        service = re.search(r'под ключ|ключ установк|с установк|установк|монтаж|услуг|мастер|бригад|фирм|компан', p)
        it = next((n for n, rx in INTENT if re.search(rx, p)), 'общий / прочее')
        if it == 'цена и заказ' and re.search(comp_rx, p) and not service:
            it = 'комплектующие и автоматика'      # «привод для откатных ворот купить» — покупка комплектующего
        cr = '; '.join(n for n, rx in CRIT if re.search(rx, p))
        mt = '; '.join(n for n, rx in MAT if re.search(rx, p))
        br = ', '.join(sorted(set(re.findall(BRAND, p))))
        rows.append(dict(query=q, region=reg, phrase=p, count=c, intent=it, criteria=cr, material=mt, brand=br,
                         source=f'Вордстат, «Топы», {m.group(2)}–{m.group(3)}; {os.path.basename(f)}', date_collected='2026-10-21'))
    tot = sum(c for _, c in ph[1:])
    sub = [r for r in rows if r['query'] == q and r['region'] == reg]
    for kind, names in (('намерение', [n for n, _ in INTENT] + ['общий / прочее']), ('критерий', [n for n, _ in CRIT]), ('материал', [n for n, _ in MAT])):
        for n in names:
            if kind == 'критерий' and q == 'откатные ворота' and n == 'с воротами и калиткой':
                continue
            s = sum(r['count'] for r in sub if (r['intent'] == n if kind == 'намерение' else n in r[{'критерий': 'criteria', 'материал': 'material'}[kind]]))
            summ.append(dict(query=q, region=reg, head_frequency=head[1], phrases=len(ph) - 1, dimension=kind, value=n, sum_count=s, share_pct=round(100 * s / tot, 1)))
    bsum = sum(r['count'] for r in sub if r['brand'])
    summ.append(dict(query=q, region=reg, head_frequency=head[1], phrases=len(ph) - 1, dimension='бренды', value='фразы с брендом', sum_count=bsum, share_pct=round(100 * bsum / tot, 1)))
def w(p, rs):
    with open(f'{B}/data/{p}.csv', 'w', encoding='utf-8', newline='') as fh:
        d = csv.DictWriter(fh, fieldnames=list(rs[0].keys())); d.writeheader(); d.writerows(rs)
# в рабочий файл — все фразы, кроме номеров телефонов; в опубликованный (data/ws_tops.csv) — фразы с частотой от 10 без цифровых последовательностей от 7 знаков
rows = [r for r in rows if not re.search(r'\d{7,}', r['phrase'])]
MO_RX = r'московск|подмоск|\bмоскв|раменск|чехов|дмитров|серпухов|сергиев|коломн|подольск|щелков|ступин|егорьевск|\bклин\b|\bклину\b|талдом|волоколамск|воскресенск|\bистр|одинцов|мытищ|королев|балаших|наро.фоминск|можайск|куровск|орехово|шатур|апрелевк|климовск|павловск|бронниц|зарайск|ногинск|солнечногорск|домодедов|пушкин|видное|звенигород|лобн|химк|красногорск|люберц|электросталь|жуковск|дубн'
mo = []
for q in sorted({r['query'] for r in rows}):
    a = {r['phrase']: r['count'] for r in rows if r['query'] == q and r['region'].startswith('Россия без 16')}
    b = {r['phrase']: r['count'] for r in rows if r['query'] == q and not r['region'].startswith('Россия без 16')}
    for p_, c in a.items():
        if re.search(MO_RX, p_):
            mo.append(dict(query=q, phrase=p_, count_incl_msk_mo=c, count_rf_without_msk_mo=b.get(p_, 0),
                           note='регион с Москвой и МО: Россия без 16 областей Центра; второй столбец — Россия без Москвы и МО',
                           source='Вордстат, «Топы запросов», 20.09–20.10.2026; выгрузки пользователя 21.10.2026', date_collected='2026-10-21'))
mo.sort(key=lambda r: (r['query'], -r['count_incl_msk_mo']))
w('ws_tops_mo_phrases', mo)
w('ws_tops_all', rows); w('ws_tops', [r for r in rows if r['count'] >= 10]); w('ws_tops_intents', summ)
for s in summ: print(s['query'][:10], s['dimension'], s['value'], s['sum_count'], s['share_pct'])
